"use client";

import * as React from "react";
import { Accordion as AccordionPrimitive } from "@base-ui/react/accordion";
import { Icon } from "@iconify/react";

import { cn } from "@/lib/utils";
import { cardSlab, focusRing } from "./_shared";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

/**
 * Paddock Accordion: a stack of questions on one white bordered card with a
 * rounded corner, each row divided from the next by a 1px cool border.
 */
const Accordion = React.forwardRef<
  HTMLDivElement,
  WithClassName<AccordionPrimitive.Root.Props>
>(({ className, ...props }, ref) => (
  <AccordionPrimitive.Root
    ref={ref}
    data-slot="accordion"
    className={cn("w-full rounded-xl px-4", cardSlab, className)}
    {...props}
  />
));
Accordion.displayName = "Accordion";

/** Paddock AccordionItem: one row, divided from the next by a 1px border. */
const AccordionItem = React.forwardRef<
  HTMLDivElement,
  WithClassName<AccordionPrimitive.Item.Props>
>(({ className, ...props }, ref) => (
  <AccordionPrimitive.Item
    ref={ref}
    data-slot="accordion-item"
    className={cn("border-b border-border last:border-b-0", className)}
    {...props}
  />
));
AccordionItem.displayName = "AccordionItem";

/**
 * Paddock AccordionTrigger: the question in semibold card-title type, with a
 * muted chevron at the end that turns over as the answer opens.
 */
const AccordionTrigger = React.forwardRef<
  HTMLButtonElement,
  WithClassName<AccordionPrimitive.Trigger.Props>
>(({ className, children, ...props }, ref) => (
  <AccordionPrimitive.Header data-slot="accordion-header" className="flex">
    <AccordionPrimitive.Trigger
      ref={ref}
      data-slot="accordion-trigger"
      className={cn(
        "group/trigger flex flex-1 items-center justify-between gap-3 rounded-sm py-3.5 text-start",
        "text-[0.9375rem] font-semibold text-foreground",
        focusRing,
        "data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50",
        className,
      )}
      {...props}
    >
      {children}
      <Icon
        icon="mingcute:down-line"
        aria-hidden="true"
        className="size-4 shrink-0 text-muted-foreground transition-transform duration-base ease-out group-data-[panel-open]/trigger:rotate-180"
      />
    </AccordionPrimitive.Trigger>
  </AccordionPrimitive.Header>
));
AccordionTrigger.displayName = "AccordionTrigger";

/**
 * Paddock AccordionContent: the answer in muted note type. The panel grows to
 * its measured height.
 */
const AccordionContent = React.forwardRef<
  HTMLDivElement,
  WithClassName<AccordionPrimitive.Panel.Props>
>(({ className, children, ...props }, ref) => (
  <AccordionPrimitive.Panel
    ref={ref}
    data-slot="accordion-content"
    className={cn(
      "h-(--accordion-panel-height) overflow-hidden text-[0.8125rem] text-muted-foreground",
      "transition-[height] duration-base ease-out",
      "data-[starting-style]:h-0 data-[ending-style]:h-0",
    )}
    {...props}
  >
    <div className={cn("pb-3.5", className)}>{children}</div>
  </AccordionPrimitive.Panel>
));
AccordionContent.displayName = "AccordionContent";

export { Accordion, AccordionItem, AccordionTrigger, AccordionContent };
